const ConstructionPaymentAnimation: React.FC<ConstructionPaymentProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 8,
  startVolume = 1000000,
  endVolume = 5000000,
  dateText = "OCT 15, 2024",
  requisitionCount = 5,
  accentColor = "#ff5500",
  cardColor = "#1a1a1d",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const headerAppear = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14 },
  });
  const headerY = interpolate(headerAppear, [0, 1], [30, 0]);
  const headerOpacity = interpolate(headerAppear, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  const appearStart = 40;
  const totalDurationFrames = fps * durationInSeconds;
  const lastActionFrame = totalDurationFrames - 40;
  const totalStaggerTime = Math.max(0, lastActionFrame - appearStart - 20);
  const staggerDelay = totalStaggerTime / requisitionCount;

  const chunkAmount = (endVolume - startVolume) / requisitionCount;

  const cardData = Array.from({ length: requisitionCount }).map((_, i) => {
    const delay = appearStart + i * staggerDelay;
    const sentSpringValue = spring({
      frame: frame - (delay + 15),
      fps,
      config: { damping: 12, stiffness: 150 },
    });
    return { index: i, delay, sentSpringValue };
  });

  const totalSentProgress = cardData.reduce((sum, card) => sum + card.sentSpringValue, 0);
  const currentTotalVolume = startVolume + chunkAmount * totalSentProgress;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: transparentBackground
          ? "none"
          : `radial-gradient(circle at 50% 0%, ${accentColor}15 0%, transparent 60%)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      <div style={{ width: "85%", display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            marginBottom: 60,
            opacity: headerOpacity,
            transform: `translateY(${headerY}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              color: textColor,
              opacity: 0.5,
              fontSize: 20,
              fontWeight: 600,
              letterSpacing: 2,
              marginBottom: 12,
            }}
          >
            BATCH ISSUED
          </div>

          <div
            style={{
              color: accentColor,
              fontFamily: spaceFamily,
              fontSize: 28,
              fontWeight: 700,
              letterSpacing: 4,
              textTransform: "uppercase",
              marginBottom: 24,
              padding: "10px 28px",
              backgroundColor: `${accentColor}1A`,
              borderRadius: 30,
              border: `1px solid ${accentColor}40`,
            }}
          >
            {dateText}
          </div>

          <div
            style={{
              fontFamily: spaceFamily,
              fontSize: 90,
              fontWeight: 800,
              color: textColor,
              fontVariantNumeric: "tabular-nums",
              lineHeight: 1,
            }}
          >
            {new Intl.NumberFormat("en-US", {
              style: "currency",
              currency: "USD",
              maximumFractionDigits: 0,
            }).format(Math.round(currentTotalVolume))}
          </div>

          <div
            style={{
              color: textColor,
              opacity: 0.6,
              fontSize: 24,
              marginTop: 16,
            }}
          >
            TOTAL BILLING SENT
          </div>
        </div>

        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 24 }}>
          {cardData.map((data) => (
            <RequisitionCard
              key={data.index}
              index={data.index}
              delay={data.delay}
              frame={frame}
              fps={fps}
              cardColor={cardColor}
              textColor={textColor}
              accentColor={accentColor}
              amount={chunkAmount}
              sentSpringValue={data.sentSpringValue}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ConstructionPaymentAnimation;